struct Attributes {
vec3 POSITION;
vec2 TEXCOORD_0;
vec4 COLOR_0;
};
in vec3 POSITION;
in vec2 TEXCOORD_0;
in vec4 COLOR_0;
Attributes read_Attributes() { Attributes interface_value;
interface_value.POSITION = POSITION;
interface_value.TEXCOORD_0 = TEXCOORD_0;
interface_value.COLOR_0 = COLOR_0;
return interface_value; }
struct Varyings {
vec2 v_localUv;
vec2 v_sceneUv;
vec4 v_color;
};
out vec2 v_localUv;
out vec2 v_sceneUv;
out vec4 v_color;
void write_Varyings(Varyings interface_value) {
v_localUv = interface_value.v_localUv;
v_sceneUv = interface_value.v_sceneUv;
v_color = interface_value.v_color;
}
Varyings vert ( Attributes attr ) { Varyings v ;
vec4 clipPosition = renderer_MVPMat * vec4 ( attr.POSITION , 1.0 ) ;
gl_Position = clipPosition ;
vec2 screenPosition = vec2 ( clipPosition.x , clipPosition.y * camera_ProjectionParams.x ) ;
vec2 bottomOriginUv = screenPosition / max ( clipPosition.w , 0.0001 ) * 0.5 + 0.5 ;
v.v_sceneUv = vec2 ( bottomOriginUv.x , 1.0 - bottomOriginUv.y ) ;
v.v_localUv = attr.TEXCOORD_0 ;
v.v_color = attr.COLOR_0 ;
return v ; }
void main() {
Attributes input_attr = read_Attributes();
write_Varyings(vert(input_attr)); }

