    precision highp float;
    precision highp int;

        layout(std140) uniform gs_Auto_0 {
highp vec4 camera_ProjectionParams;
highp mat4 renderer_MVPMat;
highp vec2 material_SeedWorldSourceTexelSize;
highp vec2 material_SeedWorldScreenSize;
highp vec2 material_SeedWorldPanelPixelSize;
highp float material_SeedWorldCornerRadiusPixels;
highp float material_SeedWorldGlassOpacity;
